-- Seed official Tanzania regions, districts, and wards using NBS 2022 PHC ward shapefiles.
-- Source: https://www.nbs.go.tz/statistics/topic/gis

insert into public.locations (parent_id, location_type, name, latitude, longitude, is_active)
select null, 'country'::public.location_type, 'Tanzania', -6.3690, 34.8888, true
where not exists (
  select 1
  from public.locations
  where location_type = 'country'::public.location_type
    and lower(name) = 'tanzania'
);

update public.locations
set latitude = -6.3690,
    longitude = 34.8888,
    is_active = true
where location_type = 'country'::public.location_type
  and lower(name) = 'tanzania';

