update public.locations as l
set latitude = region_source.latitude,
    longitude = region_source.longitude,
    is_active = true
from region_source, country
where l.parent_id = country.id
  and l.location_type = 'region'::public.location_type
  and lower(l.name) = lower(region_source.name);

