insert into public.locations (parent_id, location_type, name, latitude, longitude, is_active)
select country.id, 'region'::public.location_type, region_source.name, region_source.latitude, region_source.longitude, true
from region_source
cross join country
where not exists (
  select 1
  from public.locations l
  where l.parent_id = country.id
    and l.location_type = 'region'::public.location_type
    and lower(l.name) = lower(region_source.name)
);

