update public.locations as l
set latitude = district_source.latitude,
    longitude = district_source.longitude,
    is_active = true
from district_source
join public.locations country
  on country.location_type = 'country'::public.location_type
 and lower(country.name) = 'tanzania'
join public.locations region
  on region.parent_id = country.id
 and region.location_type = 'region'::public.location_type
 and lower(region.name) = lower(district_source.region_name)
where l.parent_id = region.id
  and l.location_type = 'district'::public.location_type
  and lower(l.name) = lower(district_source.name);

