update public.locations as l
set latitude = ward_source.latitude,
    longitude = ward_source.longitude,
    is_active = true
from ward_source
join public.locations country
  on country.location_type = 'country'::public.location_type
 and lower(country.name) = 'tanzania'
join public.locations region
  on region.parent_id = country.id
 and region.location_type = 'region'::public.location_type
 and lower(region.name) = lower(ward_source.region_name)
join public.locations district
  on district.parent_id = region.id
 and district.location_type = 'district'::public.location_type
 and lower(district.name) = lower(ward_source.district_name)
where l.parent_id = district.id
  and l.location_type = 'ward'::public.location_type
  and lower(l.name) = lower(ward_source.name);

