insert into public.locations (parent_id, location_type, name, latitude, longitude, is_active)
select district.id, 'ward'::public.location_type, ward_source.name, ward_source.latitude, ward_source.longitude, true
from ward_source
join public.locations country
  on country.location_type = 'country'::public.location_type
 and lower(country.name) = 'tanzania'
join public.locations region
  on region.parent_id = country.id
 and region.location_type = 'region'::public.location_type
 and lower(region.name) = lower(ward_source.region_name)
join public.locations district
  on district.parent_id = region.id
 and district.location_type = 'district'::public.location_type
 and lower(district.name) = lower(ward_source.district_name)
where not exists (
  select 1
  from public.locations l
  where l.parent_id = district.id
    and l.location_type = 'ward'::public.location_type
    and lower(l.name) = lower(ward_source.name)
);

create or replace function public.normalize_listing_media_path(check_path text)
returns text
language sql
immutable
as $$
  select case
    when check_path is null then null
    else regexp_replace(check_path, '^listing-media/', '')
  end;
$$;

drop function if exists public.is_valid_listing_location(uuid);

create or replace function public.is_valid_listing_location(check_location_id uuid)
returns boolean
language plpgsql
stable
as $$
declare
  v_location public.locations%rowtype;
begin
  if check_location_id is null then
    return false;
  end if;

  select *
  into v_location
  from public.locations
  where id = check_location_id
    and is_active = true;

  if v_location.id is null then
    return false;
  end if;

  if v_location.location_type not in (
    'district'::public.location_type,
    'ward'::public.location_type,
    'area'::public.location_type,
    'street'::public.location_type
  ) then
    return false;
  end if;

  return public.location_ancestor_id(check_location_id, 'region'::public.location_type) is not null
    and public.location_ancestor_id(check_location_id, 'district'::public.location_type) is not null;
end;
$$;

drop function if exists public.build_public_location_label(uuid);

create or replace function public.build_public_location_label(check_location_id uuid)
returns text
language plpgsql
stable
as $$
declare
  v_region_name text;
  v_district_name text;
  v_ward_name text;
  v_area_name text;
  v_local_name text;
begin
  if check_location_id is null then
    return null;
  end if;

  v_region_name := public.location_ancestor_name(check_location_id, 'region'::public.location_type);
  v_district_name := public.location_ancestor_name(check_location_id, 'district'::public.location_type);
  v_ward_name := public.location_ancestor_name(check_location_id, 'ward'::public.location_type);
  v_area_name := public.location_ancestor_name(check_location_id, 'area'::public.location_type);
  v_local_name := coalesce(v_area_name, v_ward_name, v_district_name);

  if v_local_name is null and v_region_name is null then
    return null;
  end if;

  return array_to_string(
    array(
      select item
      from unnest(array[v_local_name, v_region_name]) as item
      where item is not null and btrim(item) <> ''
    ),
    ', '
  );
end;
$$;

do $$
begin
  if exists (
    select 1
    from pg_trigger
    where tgname = 'guard_listing_workflow'
      and tgrelid = 'public.listings'::regclass
  ) then
    alter table public.listings disable trigger guard_listing_workflow;
  end if;
end
$$;

update public.listings
set public_location_label = public.build_public_location_label(location_id)
where location_id is not null;

do $$
begin
  if exists (
    select 1
    from pg_trigger
    where tgname = 'guard_listing_workflow'
      and tgrelid = 'public.listings'::regclass
  ) then
    alter table public.listings enable trigger guard_listing_workflow;
  end if;
end
$$;

drop function if exists public.get_public_home_feed(
  integer,
  integer,
  uuid,
  uuid,
  double precision,
  double precision,
  text
);

create or replace function public.get_public_home_feed(
  p_limit integer default 20,
  p_page integer default 0,
  p_selected_region_id uuid default null,
  p_selected_district_id uuid default null,
  p_selected_ward_id uuid default null,
  p_selected_area_id uuid default null,
  p_latitude double precision default null,
  p_longitude double precision default null,
  p_session_seed text default null
)
returns table (
  listing_id uuid,
  title text,
  public_location_label text,
  price_amount numeric,
  price_period text,
  category_id uuid,
  category_name text,
  category_slug text,
  category_icon_key text,
  home_feed_weight integer,
  cover_storage_path text,
  region_id uuid,
  district_id uuid
)
language sql
stable
security definer
set search_path = public
as $$
  with eligible as (
    select
      l.id as listing_id,
      l.title,
      l.public_location_label,
      l.price_amount,
      l.price_period::text as price_period,
      c.id as category_id,
      c.name as category_name,
      c.slug as category_slug,
      c.icon_key as category_icon_key,
      c.home_feed_weight,
      public.normalize_listing_media_path(lm.storage_path) as cover_storage_path,
      public.location_ancestor_id(l.location_id, 'region'::public.location_type) as region_id,
      public.location_ancestor_id(l.location_id, 'district'::public.location_type) as district_id,
      public.location_ancestor_id(l.location_id, 'ward'::public.location_type) as ward_id,
      public.location_ancestor_id(l.location_id, 'area'::public.location_type) as area_id,
      coalesce(l.published_at, l.created_at) as freshness_at,
      case
        when p_latitude is not null
         and p_longitude is not null
         and loc.latitude is not null
         and loc.longitude is not null
        then power(loc.latitude - p_latitude, 2) + power(loc.longitude - p_longitude, 2)
        else null
      end as gps_distance_score,
      case
        when p_selected_area_id is not null
         and public.location_ancestor_id(l.location_id, 'area'::public.location_type) = p_selected_area_id then 1
        when p_selected_ward_id is not null
         and public.location_ancestor_id(l.location_id, 'ward'::public.location_type) = p_selected_ward_id then 2
        when p_selected_district_id is not null
         and public.location_ancestor_id(l.location_id, 'district'::public.location_type) = p_selected_district_id then 3
        when p_selected_region_id is not null
         and public.location_ancestor_id(l.location_id, 'region'::public.location_type) = p_selected_region_id then 4
        when p_latitude is not null and p_longitude is not null then 5
        else 6
      end as priority_group,
      (
        ((('x' || substr(
          md5(coalesce(p_session_seed, to_char(current_date, 'YYYYMMDD')) || ':' || l.id::text),
          1,
          8
        ))::bit(32)::bigint)::numeric + 1)
      ) / 4294967296::numeric as random_unit,
      (
        p_selected_region_id is not null
        or p_selected_district_id is not null
        or p_selected_ward_id is not null
        or p_selected_area_id is not null
        or (p_latitude is not null and p_longitude is not null)
      ) as has_location_signal
    from public.listings l
    join public.asset_categories c on c.id = l.category_id
    left join public.locations loc on loc.id = l.location_id
    left join public.listing_media lm
      on lm.listing_id = l.id
     and lm.is_cover = true
    where public.is_listing_public(l.id)
  )
  select
    listing_id,
    title,
    public_location_label,
    price_amount,
    price_period,
    category_id,
    category_name,
    category_slug,
    category_icon_key,
    home_feed_weight,
    cover_storage_path,
    region_id,
    district_id
  from eligible
  order by
    case when has_location_signal then priority_group else 0 end asc,
    case when has_location_signal then gps_distance_score end nulls last,
    case when not has_location_signal then random_unit end asc nulls last,
    freshness_at desc,
    listing_id
  offset greatest(coalesce(p_page, 0), 0) * greatest(least(coalesce(p_limit, 20), 50), 1)
  limit greatest(least(coalesce(p_limit, 20), 50), 1);
$$;

drop function if exists public.get_public_listings(
  text,
  text,
  uuid,
  uuid,
  integer,
  integer,
  double precision,
  double precision,
  text
);

create or replace function public.get_public_listings(
  p_category_slug text default null,
  p_search_text text default null,
  p_region_id uuid default null,
  p_district_id uuid default null,
  p_ward_id uuid default null,
  p_area_id uuid default null,
  p_limit integer default 20,
  p_page integer default 0,
  p_latitude double precision default null,
  p_longitude double precision default null,
  p_session_seed text default null
)
returns table (
  listing_id uuid,
  title text,
  public_location_label text,
  price_amount numeric,
  price_period text,
  category_id uuid,
  category_name text,
  category_slug text,
  category_icon_key text,
  home_feed_weight integer,
  cover_storage_path text,
  region_id uuid,
  district_id uuid
)
language sql
stable
security definer
set search_path = public
as $$
  with eligible as (
    select
      l.id as listing_id,
      l.title,
      l.public_location_label,
      l.price_amount,
      l.price_period::text as price_period,
      c.id as category_id,
      c.name as category_name,
      c.slug as category_slug,
      c.icon_key as category_icon_key,
      c.home_feed_weight,
      public.normalize_listing_media_path(lm.storage_path) as cover_storage_path,
      public.location_ancestor_id(l.location_id, 'region'::public.location_type) as region_id,
      public.location_ancestor_id(l.location_id, 'district'::public.location_type) as district_id,
      public.location_ancestor_id(l.location_id, 'ward'::public.location_type) as ward_id,
      public.location_ancestor_id(l.location_id, 'area'::public.location_type) as area_id,
      coalesce(l.published_at, l.created_at) as freshness_at,
      case
        when p_latitude is not null
         and p_longitude is not null
         and loc.latitude is not null
         and loc.longitude is not null
        then power(loc.latitude - p_latitude, 2) + power(loc.longitude - p_longitude, 2)
        else null
      end as gps_distance_score,
      case
        when p_area_id is not null
         and public.location_ancestor_id(l.location_id, 'area'::public.location_type) = p_area_id then 1
        when p_ward_id is not null
         and public.location_ancestor_id(l.location_id, 'ward'::public.location_type) = p_ward_id then 2
        when p_district_id is not null
         and public.location_ancestor_id(l.location_id, 'district'::public.location_type) = p_district_id then 3
        when p_region_id is not null
         and public.location_ancestor_id(l.location_id, 'region'::public.location_type) = p_region_id then 4
        when p_latitude is not null and p_longitude is not null then 5
        else 6
      end as priority_group,
      (
        ((('x' || substr(
          md5(coalesce(p_session_seed, to_char(current_date, 'YYYYMMDD')) || ':' || l.id::text),
          1,
          8
        ))::bit(32)::bigint)::numeric + 1)
      ) / 4294967296::numeric as random_unit,
      (
        p_region_id is not null
        or p_district_id is not null
        or p_ward_id is not null
        or p_area_id is not null
        or (p_latitude is not null and p_longitude is not null)
      ) as has_location_signal
    from public.listings l
    join public.asset_categories c on c.id = l.category_id
    left join public.locations loc on loc.id = l.location_id
    left join public.listing_media lm
      on lm.listing_id = l.id
     and lm.is_cover = true
    where public.is_listing_public(l.id)
      and (
        p_category_slug is null
        or c.slug = p_category_slug
      )
      and (
        p_search_text is null
        or btrim(p_search_text) = ''
        or l.title ilike '%' || btrim(p_search_text) || '%'
        or l.description ilike '%' || btrim(p_search_text) || '%'
        or l.public_location_label ilike '%' || btrim(p_search_text) || '%'
        or c.name ilike '%' || btrim(p_search_text) || '%'
      )
  )
  select
    listing_id,
    title,
    public_location_label,
    price_amount,
    price_period,
    category_id,
    category_name,
    category_slug,
    category_icon_key,
    home_feed_weight,
    cover_storage_path,
    region_id,
    district_id
  from eligible
  order by
    case when has_location_signal then priority_group else 0 end asc,
    case when has_location_signal then gps_distance_score end nulls last,
    case when not has_location_signal then random_unit end asc nulls last,
    case
      when p_search_text is null or btrim(p_search_text) = '' then 0
      when title ilike btrim(p_search_text) || '%' then 0
      else 1
    end,
    freshness_at desc,
    listing_id
  offset greatest(coalesce(p_page, 0), 0) * greatest(least(coalesce(p_limit, 20), 50), 1)
  limit greatest(least(coalesce(p_limit, 20), 50), 1);
$$;

